package org.com.sharekhan.migration;
import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.com.sharekhan.entity.*;import org.com.sharekhan.repository.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Component;import java.util.*;
@Component @Slf4j @RequiredArgsConstructor @ConditionalOnExpression("'${app.configuration.postgres.enabled:false}' == 'true' and '${app.configuration.postgres.backfill-on-startup:false}' == 'true'")
public class ConfigurationBackfillRunner implements ApplicationRunner{
 private final UserConfigRepository configs;private final AdminUserRepository admins;private final AccessTokenRepository tokens;@Qualifier("auditPostgresJdbcTemplate") private final NamedParameterJdbcTemplate pg;
 public void run(ApplicationArguments a){copy("user_config","id,user_id,app_user_id,key_name,config_value,enabled",":id,:userId,:appUserId,:keyName,:value,:enabled",configs.findAll());copy("admin_user","id,username,password,roles",":id,:username,:password,:roles",admins.findAll());copy("access_token","id,token,expiry,broker_name,user_id,broker_credentials_id",":id,:token,:expiry,:brokerName,:userId,:brokerCredentialsId",tokens.findAll());sync("user_config");sync("admin_user");sync("access_token");if(count("user_config")!=configs.count()||count("admin_user")!=admins.count()||count("access_token")!=tokens.count())throw new IllegalStateException("Configuration backfill count mismatch");log.info("PostgreSQL configuration backfill complete: userConfig={} admins={} accessTokens={}",configs.count(),admins.count(),tokens.count());}
 private void copy(String table,String c,String v,List<?> rows){if(rows.isEmpty())return;pg.batchUpdate("INSERT INTO "+table+" ("+c+") OVERRIDING SYSTEM VALUE VALUES ("+v+") ON CONFLICT (id) DO NOTHING",rows.stream().map(BeanPropertySqlParameterSource::new).toArray(SqlParameterSource[]::new));} private long count(String t){Long n=pg.getJdbcTemplate().queryForObject("SELECT COUNT(*) FROM "+t,Long.class);return n==null?0:n;}private void sync(String t){pg.getJdbcTemplate().execute("SELECT setval(pg_get_serial_sequence('"+t+"','id'),COALESCE((SELECT MAX(id) FROM "+t+"),1),true)");}
}
